package provider

import (
	"bufio"
	"context"
	"encoding/json"
	"math"
	"os"
	"testing"
)

// Fixtures are generated by serde_json 1.0.151 and 1.0.154 with default
// features, as used by Rauthy 0.36.2 and 0.37.2. Both versions agree.
func TestJSONNumbersSerdeContract(t *testing.T) {
	file, err := os.Open("testdata/serde_json_numbers.jsonl")
	if err != nil {
		t.Fatal(err)
	}
	defer file.Close()
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		var fixture struct {
			Input  string `json:"input"`
			Stored string `json:"stored"`
			Bits   uint64 `json:"bits"`
		}
		if err = json.Unmarshal(scanner.Bytes(), &fixture); err != nil {
			t.Fatal(err)
		}
		t.Run(fixture.Input, func(t *testing.T) {
			if got := math.Float64bits(serdeJSONFloat(fixture.Input)); got != fixture.Bits {
				t.Errorf("bits = %x, want %x", got, fixture.Bits)
			}
			same, d := newJSONString(
				fixture.Input,
			).StringSemanticEquals(context.Background(), newJSONString(fixture.Stored))
			if d.HasError() || !same {
				t.Errorf("stored %s differs: %v", fixture.Stored, d)
			}
		})
	}
	if err = scanner.Err(); err != nil {
		t.Fatal(err)
	}
}
